{"command":"python3 << 'PY'
import json, subprocess, os

def get(p,r,c):
    # use ft2 call
    import os
    out = os.popen(f"ft2 call pattern_get_cell '{{\"pattern\":{p},\"row\":{r},\"channel\":{c}}}'").read()
    return out

# occupancy: count non-empty per pattern/channel by sampling via a batch
calls = []
for p in range(8):
    for r in range(64):
        for c in [0,1,2,4,6,10]:
            calls.append({"name":"pattern_get_cell","arguments":{"pattern":p,"row":r,"channel":c}})
# too many, do pattern 0 all channels all rows that are multiples of 4
calls = []
for r in range(64):
    for c in range(16):
        calls.append({"name":"pattern_get_cell","arguments":{"pattern":0,"row":r,"channel":c}})
json.dump(calls, open('/tmp/getp0.json','w'))
print(len(calls))
PY
ft2 batch /tmp/getp0.json > /tmp/p0cells.txt
python3 << 'PY'
import json, re
text = open('/tmp/p0cells.txt').read()
# each line is a JSON object
rows = {}
for line in text.splitlines():
    line=line.strip()
    if not line: continue
    try:
        o=json.loads(line)
    except Exception:
        continue
    if o.get('isError'): continue
    t=o['content'][0]['text']
    cell=json.loads(t)
    if cell.get('note',0) or cell.get('instrument',0) or cell.get('effect',0) or cell.get('volume',0):
        r=cell['row']; c=cell['channel']
        rows.setdefault(r, []).append((c, cell.get('note_name',''), cell.get('instrument',0), cell.get('volume',0), cell.get('effect',0), cell.get('effect_param',0)))

print('occupied rows', len(rows))
